def parse_iso(text) -> datetime | None:
    """An ISO 8601 time with `Z` or an offset (data.md, section 2); None when it is not one."""
    if not isinstance(text, str) or not _ISO.match(text):
        return None
    try:
        t = datetime.fromisoformat(text.replace(",", "."))
    except ValueError:
        return None
    return t if t.tzinfo is not None else None


def parse_state_time(text) -> datetime | None:
