"""policy.ini (docs/policy.md)."""

import re
from datetime import timedelta, timezone
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError

_SIZE = re.compile(r"([0-9]+)([KMGkmg]?)\Z")
_DURATION = re.compile(r"([0-9]+)([mhd])\Z")
_OFFSET = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")
_COUNT = re.compile(r"[0-9]+\Z")
_UNITS = {"": 1, "k": 1024, "m": 1024 * 1024, "g": 1024 * 1024 * 1024}
_SPAN = {"m": timedelta(minutes=1), "h": timedelta(hours=1), "d": timedelta(days=1)}


class Settings:
    __slots__ = ("max_size", "max_age", "naming", "offset", "compress_after", "keep", "keep_days")

    def __init__(self, **kw):
        for k in self.__slots__:
            setattr(self, k, kw[k])


BUILTIN = {
    "max_size": None,
    "max_age": None,
    "naming": "numbered",
    "offset": timezone.utc,
    "compress_after": 1,
    "keep": 5,
    "keep_days": None,
}


def _bad(msg: str):
    return DataError("policy", f"policy.ini: {msg}")


def _size(v):
    if v == "off":
        return None
    m = _SIZE.match(v)
    if not m:
        raise ValueError(v)
    return int(m.group(1)) * _UNITS[m.group(2).lower()]


def _duration(v):
    if v == "off":
        return None
    m = _DURATION.match(v)
    if not m:
        raise ValueError(v)
    return int(m.group(1)) * _SPAN[m.group(2)]


def _naming(v):
    if v not in ("numbered", "dated"):
        raise ValueError(v)
    return v


def _offset(v):
    m = _OFFSET.match(v)
    if not m:
        raise ValueError(v)
    h, mi = int(m.group(2)), int(m.group(3))
    if h > 23 or mi > 59:
        raise ValueError(v)
    d = timedelta(hours=h, minutes=mi)
    return timezone(-d if m.group(1) == "-" else d)


def _count(minimum):
    def parse(v):
        if not _COUNT.match(v):
            raise ValueError(v)
        n = int(v)
        if n < minimum:
            raise ValueError(v)
        return n

    return parse


def _keep_days(v):
    if v == "off":
        return None
    return _count(1)(v)


_PARSERS = {
    "max_size": _size,
    "max_age": _duration,
    "naming": _naming,
    "offset": _offset,
    "compress_after": _count(0),
    "keep": _count(1),
    "keep_days": _keep_days,
}


class Policy:
    def __init__(self, defaults: dict, sections: dict):
        self._defaults = defaults
        self.sections = sections  # stream name -> {key: value}

    def for_stream(self, name: str) -> Settings:
        vals = dict(BUILTIN)
        vals.update(self._defaults)
        vals.update(self.sections.get(name, {}))
        return Settings(**vals)


def load(path: Path) -> Policy:
    if not path.exists():
        return Policy({}, {})
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise _bad(str(e)) from None
    defaults: dict = {}
    sections: dict = {}
    current = None
    seen_defaults = False
    for lineno, raw in enumerate(text.splitlines(), 1):
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line.startswith("["):
            if not line.endswith("]"):
                raise _bad(f"line {lineno}: bad section header")
            title = line[1:-1]
            if title == "defaults":
                if seen_defaults:
                    raise _bad(f"line {lineno}: section defaults given twice")
                seen_defaults = True
                current = defaults
            elif title.startswith("stream ") and streams.valid(title[7:]):
                name = title[7:]
                if name in sections:
                    raise _bad(f"line {lineno}: section {name} given twice")
                current = sections[name] = {}
            else:
                raise _bad(f"line {lineno}: unknown section")
            continue
        if current is None or "=" not in line:
            raise _bad(f"line {lineno}: not a setting")
        key, _, value = line.partition("=")
        key, value = key.strip(), value.strip()
        if key not in _PARSERS:
            raise _bad(f"line {lineno}: unknown key {key}")
        if key in current:
            raise _bad(f"line {lineno}: key {key} given twice")
        try:
            current[key] = _PARSERS[key](value)
        except ValueError:
            raise _bad(f"line {lineno}: bad value for {key}") from None
    return Policy(defaults, sections)

"""rotate (docs/rotate.md)."""

import gzip
import re
from dataclasses import dataclass
from datetime import date, datetime, timezone
from pathlib import Path

from logkeep import dates, policy as policy_mod, state as state_mod, streams
from logkeep.errors import DataError, Refused


@dataclass
class Archive:
    name: str | None  # name before the run; None for the new archive
    key: object  # N (numbered) or (day, K) (dated)
    gz: bool
    time: str | None = None  # as stored in state.json
    new: bool = False
    final: str = ""
    compress: bool = False


def _parse_archives(logs: Path, name: str, naming: str) -> list[Archive]:
    """The archives of a stream in age order, newest first."""
    if naming == "numbered":
        rx = re.compile(re.escape(name) + r"\.log\.([1-9][0-9]*)(\.gz)?\Z")
    else:
        rx = re.compile(
            re.escape(name) + r"\.log\.([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?\Z"
        )
    found: dict[object, Archive] = {}
    if logs.is_dir():
        for p in sorted(logs.iterdir(), key=lambda q: q.name):
            m = rx.match(p.name)
            if not m or not p.is_file():
                continue
            if naming == "numbered":
                key, gz = int(m.group(1)), m.group(2) is not None
            else:
                try:
                    day = date.fromisoformat(m.group(1))
                except ValueError:
                    continue
                key = (day, int(m.group(2)) if m.group(2) else 1)
                gz = m.group(3) is not None
            if key in found:
                raise DataError("archives", f"{name}: two archives in the same place: {found[key].name} and {p.name}")
            found[key] = Archive(p.name, key, gz)
    return _order(list(found.values()), naming)


def _order(items: list[Archive], naming: str) -> list[Archive]:
    if naming == "numbered":
        return sorted(items, key=lambda a: a.key)
    return sorted(items, key=lambda a: a.key, reverse=True)


def _first_line_time(path: Path):
    try:
        with path.open("rb") as f:
            line = f.readline()
    except OSError:
        return None
    line = line.rstrip(b"\r\n")
    token = line.split(b" ", 1)[0]
    try:
        text = token.decode("utf-8")
    except UnicodeDecodeError:
        return None
    return dates.parse_iso(text)


def validate_state(doc: dict, existing: set[str]) -> None:
    for name, entry in doc["streams"].items():
        if name not in existing:
            continue
        if "opened" in entry and dates.parse_state_time(entry["opened"]) is None:
            raise DataError("state", f"{name}: opened is not a time")
        if "rotations" in entry:
            r = entry["rotations"]
            if isinstance(r, bool) or not isinstance(r, int) or r < 0:
                raise DataError("state", f"{name}: rotations is not a whole number")
        if "archives" in entry:
            arch = entry["archives"]
            if not isinstance(arch, dict):
                raise DataError("state", f"{name}: archives is not an object")
            for fname, t in arch.items():
                if dates.parse_state_time(t) is None:
                    raise DataError("state", f"{name}: time of {fname} is not a time")


def _dated_name(stream: str, key) -> str:
    day, k = key
    return f"{stream}.log.{day.isoformat()}" + (f".{k}" if k > 1 else "")


def run(ctx, names: list[str], dry_run: bool, force: bool) -> list[str]:
    pol = policy_mod.load(ctx.policy_path)
    doc = ctx.state
    logs = streams.logs_dir(ctx.data)
    existing = set(streams.active(ctx.data)) | set(pol.sections)
    validate_state(doc, existing)

    if names:
        selected = sorted(set(names))
        for n in selected:
            if n not in existing:
                raise Refused("unknown-stream", f"no stream {n}")
    else:
        selected = sorted(existing)

    now = ctx.now
    plans = []
    for name in selected:
        st = pol.for_stream(name)
        archives = _parse_archives(logs, name, st.naming)
        plans.append((name, st, archives))

    entries = doc["streams"]
    lines: list[str] = []
    n_rot = n_rem = n_comp = 0
    new_entries: dict[str, dict] = {}
    actions = []

    for name, st, archives in plans:
        entry = entries.get(name, {})
        stored = entry.get("archives", {}) if isinstance(entry.get("archives", {}), dict) else {}
        for a in archives:
            a.time = stored.get(a.name)
        log = streams.log_path(ctx.data, name)

        # section 3: whether the stream is rotated
        why = None
        if not log.is_file():
            what = "no log"
        else:
            size = log.stat().st_size
            if size == 0:
                what = "empty"
            elif force:
                what, why = "rotate (forced)", "forced"
            elif st.max_size is not None and size >= st.max_size:
                what, why = "rotate (size)", "size"
            else:
                what = "not due"
                if st.max_age is not None:
                    if "opened" in entry:
                        opened = dates.parse_state_time(entry["opened"])
                    else:
                        opened = _first_line_time(log)
                    if opened is not None and now - opened >= st.max_age:
                        what, why = "rotate (age)", "age"
        rotated = why is not None

        items = list(archives)
        if rotated:
            if st.naming == "numbered":
                new = Archive(None, 0, False, new=True)
                items.insert(0, new)
            else:
                day = now.astimezone(st.offset).date()
                ks = [a.key[1] for a in archives if a.key[0] == day]
                k = max(ks) + 1 if ks else 1
                new = Archive(None, (day, k), False, new=True)
                items = _order(items + [new], "dated")
            new.time = dates.stamp(now)

        # section 5: retention
        keep_flags = []
        for pos, a in enumerate(items, 1):
            drop = pos > st.keep
            if not drop and st.keep_days is not None and a.time is not None and not a.new:
                t = dates.parse_state_time(a.time)
                if t is not None and now - t >= st.keep_days * dates.DAY:
                    drop = True
            keep_flags.append(not drop)
        removed = [a for a, k in zip(items, keep_flags) if not k]
        remaining = [a for a, k in zip(items, keep_flags) if k]

        # section 6: names and compression
        out_lines = []
        for i, a in enumerate(remaining, 1):
            a.compress = (not a.gz) and i > st.compress_after
            gz = a.gz or a.compress
            base = f"{name}.log.{i}" if st.naming == "numbered" else _dated_name(name, a.key)
            a.final = base + (".gz" if gz else "")
            if a.new:
                out_lines.append(f"  new {a.final}")
            elif a.final != a.name:
                out_lines.append(f"  {a.final} <- {a.name}")
            else:
                out_lines.append(f"  {a.final}")
            if a.compress:
                n_comp += 1
        for a in removed:
            if a.new:
                out_lines.append(f"  remove {_dated_name(name, a.key)}")
            else:
                out_lines.append(f"  remove {a.name}")
        n_rem += len(removed)
        n_rot += 1 if rotated else 0
        lines.append(f"{name}: {what}")
        lines.extend(out_lines)

        # section 7: state
        ne: dict = {}
        if rotated:
            ne["opened"] = dates.stamp(now)
        elif "opened" in entry:
            ne["opened"] = entry["opened"]
        ne["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        ne["archives"] = {a.final: a.time for a in remaining if a.time is not None}
        new_entries[name] = ne
        actions.append((name, log, rotated, [a for a in removed], remaining))

    lines.append(f"{n_rot} rotated, {n_rem} removed, {n_comp} compressed")
    if dry_run:
        lines.append("dry run: nothing written")
        return lines

    for name, log, rotated, removed, remaining in actions:
        _apply(logs, name, log, rotated, removed, remaining)
    entries.update(new_entries)
    ctx.data.mkdir(parents=True, exist_ok=True)
    state_mod.save(ctx.state_path, doc)
    return lines


def _apply(logs: Path, name: str, log: Path, rotated: bool, removed, remaining) -> None:
    for a in removed:
        if not a.new:
            (logs / a.name).unlink()
    moves = []  # (archive, temp path)
    counter = 0

    def temp() -> Path:
        nonlocal counter
        while True:
            counter += 1
            p = logs / f".logkeep-{name}-{counter}.tmp"
            if not p.exists():
                return p

    for a in remaining:
        if not a.new and (a.final != a.name):
            t = temp()
            (logs / a.name).rename(t)
            moves.append((a, t))
    if rotated:
        new = next((a for a in remaining if a.new), None)
        if new is not None:
            t = temp()
            log.rename(t)
            moves.append((new, t))
        else:
            log.write_bytes(b"")
            log.write_bytes(b"")
        if new is not None:
            log.write_bytes(b"")
    for a, t in moves:
        dest = logs / a.final
        if a.compress:
            data = t.read_bytes()
            dest.write_bytes(gzip.compress(data, mtime=0))
            t.unlink()
        else:
            t.rename(dest)
    # in-place compression of archives whose name does not otherwise change cannot happen:
    # compressing always adds .gz, so every compressed archive was moved above.

