class _RotateParser(_Parser):
    """`rotate [--dry-run] [--force] [STREAM ...]`, options and streams in any order."""

    def parse_known_args(self, args=None, namespace=None):
        args = list(args or [])
        if any(a in ("-h", "--help") for a in args[: args.index("--") if "--" in args else len(args)]):
            return super().parse_known_args(args, namespace)
        ns = namespace if namespace is not None else argparse.Namespace()
        ns.dry_run = ns.force = False
        names = []
        rest = False
        for a in args:
            if rest:
                names.append(a)
            elif a == "--":
                rest = True
            elif a == "--dry-run":
                ns.dry_run = True
            elif a == "--force":
                ns.force = True
            elif a.startswith("-") and a != "-":
                self.error(f"unrecognized option: {a}")
            else:
                names.append(a)
        ns.streams = [_stream(n) for n in names]
        return ns, []


def cmd_rotate(ctx, a):
    from logkeep import rotate

    return rotate.run(ctx, a.streams, a.dry_run, a.force)


